@group(0) @binding(0) var<uniform> resolution: vec2<f32>;

@fragment
fn main(@builtin(position) pixel: vec4<f32>) -> @location(0) vec4<f32> {
    let x = i32(pixel.x);
    let y = i32(pixel.y);
    if (x < 16 && y < 16) { return vec4<f32>(1.0, 0.0, 0.0, 1.0); }
    if (x >= 241 && y < 16) { return vec4<f32>(0.0, 1.0, 0.0, 1.0); }
    if (x < 16 && y >= 113) { return vec4<f32>(0.0, 0.0, 1.0, 1.0); }
    if (x >= 241 && y >= 113) { return vec4<f32>(1.0, 1.0, 0.0, 1.0); }
    let uv = pixel.xy / resolution;
    return vec4<f32>(uv.x, uv.y, 1.0 - uv.x * 0.5, 1.0);
}

@group(0) @binding(0) var<uniform> resolution: vec2<f32>;

struct SplitOutput {
    @location(0) first: vec4<f32>,
    @location(1) second: vec4<f32>,
}

@fragment
fn main(@builtin(position) pixel: vec4<f32>) -> SplitOutput {
    let uv = pixel.xy / resolution;
    return SplitOutput(vec4<f32>(uv.x, 0.0, 0.0, 1.0),
                       vec4<f32>(0.0, uv.y, 0.0, 1.0));
}

@group(0) @binding(0) var<uniform> resolution: vec2<f32>;
@group(0) @binding(1) var firstTex: texture_2d<f32>;
@group(0) @binding(2) var secondTex: texture_2d<f32>;

@fragment
fn main(@builtin(position) pixel: vec4<f32>) -> @location(0) vec4<f32> {
    let coords = vec2<i32>(pixel.xy);
    let first = textureLoad(firstTex, coords, 0);
    let second = textureLoad(secondTex, coords, 0);
    let uv = pixel.xy / resolution;
    return vec4<f32>(first.r, second.g, 1.0 - uv.x, 1.0);
}

@group(0) @binding(0) var volTex: texture_3d<f32>;
@group(0) @binding(1) var volSampler: sampler;
@fragment
fn main(@builtin(position) pixel: vec4<f32>) -> @location(0) vec4<f32> {
  let x = i32(pixel.x) % 8;
  let y = i32(pixel.y) % 8;
  let z = (i32(pixel.x) / 32) % 8;
  let coord = (vec3<f32>(f32(x), f32(y), f32(z)) +
    vec3<f32>(0.37, 0.61, 0.42)) / 8.0;
  return textureSampleLevel(volTex, volSampler, coord, 0.0);
}

@group(0) @binding(0) var volTex: texture_3d<f32>;
@fragment
fn main(@builtin(position) pixel: vec4<f32>) -> @location(0) vec4<f32> {
  let x = i32(pixel.x) % 8;
  let y = i32(pixel.y) % 8;
  let z = (i32(pixel.x) / 32 + i32(pixel.y) / 32) % 8;
  return textureLoad(volTex, vec3<i32>(x, y, z), 0);
}

@group(0) @binding(0) var<uniform> resolution: vec2<f32>;

@fragment
fn main(@builtin(position) pixel: vec4<f32>) -> @location(0) vec4<f32> {
    let uv = pixel.xy / resolution;
    let coords = vec2<i32>(uv * resolution);
    let checker = (coords.x + coords.y) & 1;
    return select(vec4<f32>(0.0, 0.0, 0.0, 1.0),
                  vec4<f32>(1.0, 1.0, 1.0, 1.0), checker == 1);
}

@group(0) @binding(0) var<uniform> resolution: vec2<f32>;
@group(0) @binding(1) var inputTex: texture_2d<f32>;
@group(0) @binding(2) var inputSampler: sampler;

@fragment
fn main(@builtin(position) pixel: vec4<f32>) -> @location(0) vec4<f32> {
    let uv = (pixel.xy + vec2<f32>(0.25, 0.25)) / resolution;
    return textureSample(inputTex, inputSampler, uv);
}

@group(0) @binding(0) var volumeOut: texture_storage_3d<rgba8unorm, write>;
@compute @workgroup_size(4, 4, 4)
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
  if (any(gid >= vec3<u32>(8u, 8u, 8u))) { return; }
  textureStore(volumeOut, vec3<i32>(gid), vec4<f32>(f32(gid.x) / 7.0, f32(gid.y) / 7.0, f32(gid.z) / 7.0, 1.0));
}

@group(0) @binding(0) var volTex: texture_3d<f32>;
@fragment
fn main(@builtin(position) pixel: vec4<f32>) -> @location(0) vec4<f32> {
  let x = i32(pixel.x) % 8;
  let y = i32(pixel.y) % 8;
  let z = (i32(pixel.x) / 32 + i32(pixel.y) / 32) % 8;
  return textureLoad(volTex, vec3<i32>(x, y, z), 0);
}

// Edge Glow, pass 2: the input posterized to `levels` steps per channel,
// mixed toward the glow color by the edge strength.

struct Uniforms {
    levels: i32,
    glow: vec3<f32>,
}

@group(0) @binding(0) var inputTex: texture_2d<f32>;
@group(0) @binding(1) var edgeTex: texture_2d<f32>;
@group(0) @binding(2) var<uniform> uniforms: Uniforms;

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let c = vec2<i32>(pos.xy);
    let base = textureLoad(inputTex, c, 0);
    let edge = clamp(textureLoad(edgeTex, c, 0).r, 0.0, 1.0);
    let steps = f32(max(uniforms.levels, 2) - 1);
    let poster = floor(base.rgb * steps + vec3<f32>(0.5, 0.5, 0.5)) / steps;
    return vec4<f32>(mix(poster, uniforms.glow, edge), base.a);
}

// Edge Glow, pass 1: Sobel gradient magnitude of the input's luminance,
// scaled by strength (texel loads, edges clamped).

struct Uniforms {
    strength: f32,
}

@group(0) @binding(0) var inputTex: texture_2d<f32>;
@group(0) @binding(1) var<uniform> uniforms: Uniforms;

fn luma(c: vec3<f32>) -> f32 {
    return dot(c, vec3<f32>(0.2126, 0.7152, 0.0722));
}

fn tap(p: vec2<i32>, size: vec2<i32>) -> f32 {
    let q = clamp(p, vec2<i32>(0, 0), size - vec2<i32>(1, 1));
    return luma(textureLoad(inputTex, q, 0).rgb);
}

@fragment
fn main(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {
    let size = vec2<i32>(textureDimensions(inputTex));
    let c = vec2<i32>(pos.xy);
    let tl = tap(c + vec2<i32>(-1, -1), size);
    let t = tap(c + vec2<i32>(0, -1), size);
    let tr = tap(c + vec2<i32>(1, -1), size);
    let l = tap(c + vec2<i32>(-1, 0), size);
    let r = tap(c + vec2<i32>(1, 0), size);
    let bl = tap(c + vec2<i32>(-1, 1), size);
    let b = tap(c + vec2<i32>(0, 1), size);
    let br = tap(c + vec2<i32>(1, 1), size);
    let gx = (tr + 2.0 * r + br) - (tl + 2.0 * l + bl);
    let gy = (bl + 2.0 * b + br) - (tl + 2.0 * t + tr);
    let g = sqrt(gx * gx + gy * gy) * uniforms.strength;
    return vec4<f32>(g, g, g, 1.0);
}

